import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"覆盖核对与差异表","description":"","frontmatter":{},"headers":[],"relativePath":"research/coverage.md","filePath":"research/coverage.md","lastUpdated":1791575433000}`),a={name:`research/coverage.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="覆盖核对与差异表" tabindex="-1">覆盖核对与差异表 <a class="header-anchor" href="#覆盖核对与差异表" aria-label="Permalink to “覆盖核对与差异表”">​</a></h1><p>核对口径：把权威书籍与文档的目录拆成条目，逐条对站内 <code>docs/</code> 下的文件；站内自己的三处交叉引用（简介、参考、侧栏与各目录导读）另做一致性核对。核对时间：2026-10-08。来源编号见<a href="/hello-design-patterns/research/overview#来源清单">调研总览的来源清单</a>。</p><h2 id="表-1-gof-23-个模式-×-站内覆盖" tabindex="-1">表 1：GoF 23 个模式 × 站内覆盖 <a class="header-anchor" href="#表-1-gof-23-个模式-×-站内覆盖" aria-label="Permalink to “表 1：GoF 23 个模式 × 站内覆盖”">​</a></h2><p>结论：23/23 全部有正文页，不需要补。</p><table tabindex="0"><thead><tr><th>分类</th><th>模式与站内链接</th><th>覆盖</th></tr></thead><tbody><tr><td>创建型 5</td><td><a href="/hello-design-patterns/creational/abstract-factory">抽象工厂</a>、<a href="/hello-design-patterns/creational/builder">建造者</a>、<a href="/hello-design-patterns/creational/factory-method">工厂方法</a>、<a href="/hello-design-patterns/creational/prototype">原型</a>、<a href="/hello-design-patterns/creational/singleton">单例</a></td><td>5/5</td></tr><tr><td>结构型 7</td><td><a href="/hello-design-patterns/structural/adapter">适配器</a>、<a href="/hello-design-patterns/structural/bridge">桥接</a>、<a href="/hello-design-patterns/structural/composite">组合</a>、<a href="/hello-design-patterns/structural/decorator">装饰</a>、<a href="/hello-design-patterns/structural/facade">外观</a>、<a href="/hello-design-patterns/structural/flyweight">享元</a>、<a href="/hello-design-patterns/structural/proxy">代理</a></td><td>7/7</td></tr><tr><td>行为型 11</td><td><a href="/hello-design-patterns/behavioral/chain-of-responsibility">责任链</a>、<a href="/hello-design-patterns/behavioral/command">命令</a>、<a href="/hello-design-patterns/behavioral/interpreter">解释器</a>、<a href="/hello-design-patterns/behavioral/iterator">迭代器</a>、<a href="/hello-design-patterns/behavioral/mediator">中介者</a>、<a href="/hello-design-patterns/behavioral/memento">备忘录</a>、<a href="/hello-design-patterns/behavioral/observer">观察者</a>、<a href="/hello-design-patterns/behavioral/state">状态</a>、<a href="/hello-design-patterns/behavioral/strategy">策略</a>、<a href="/hello-design-patterns/behavioral/template-method">模板方法</a>、<a href="/hello-design-patterns/behavioral/visitor">访问者</a></td><td>11/11</td></tr></tbody></table><p>GoF 之外站内另有的 24 个条目（多例、对象池、服务定位器、动态/保护/远程/虚拟代理、智能指针、双向桥接、依赖注入、回调、DSL、快照、并发 8 条、其他 4 条）不在本表，它们的取舍见表 2。</p><h2 id="表-2-调研条目-×-站内缺口" tabindex="-1">表 2：调研条目 × 站内缺口 <a class="header-anchor" href="#表-2-调研条目-×-站内缺口" aria-label="Permalink to “表 2：调研条目 × 站内缺口”">​</a></h2><h3 id="_2a-本次补齐的-14-项缺口" tabindex="-1">2a. 本次补齐的 14 项缺口 <a class="header-anchor" href="#_2a-本次补齐的-14-项缺口" aria-label="Permalink to “2a. 本次补齐的 14 项缺口”">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>缺口条目</th><th>来源</th><th>新篇</th></tr></thead><tbody><tr><td>1</td><td>反模式方法论（坏味道—反模式—模式三层关系）</td><td>[S6][S7]</td><td><a href="/hello-design-patterns/anti-patterns/overview">反模式导读</a></td></tr><tr><td>2</td><td>神对象（God Object）</td><td>[S6][S25]</td><td><a href="/hello-design-patterns/anti-patterns/god-object">神对象</a></td></tr><tr><td>3</td><td>大泥球（Big Ball of Mud）</td><td>[S8]</td><td><a href="/hello-design-patterns/anti-patterns/big-ball-of-mud">大泥球</a></td></tr><tr><td>4</td><td>金锤子（Golden Hammer）</td><td>[S7][S17]</td><td><a href="/hello-design-patterns/anti-patterns/golden-hammer">金锤子</a></td></tr><tr><td>5</td><td>意面代码（Spaghetti Code）</td><td>[S7][S17]</td><td><a href="/hello-design-patterns/anti-patterns/spaghetti-code">意面代码</a></td></tr><tr><td>6</td><td>贫血模型（Anemic Domain Model）</td><td>[S26][S5]</td><td><a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a></td></tr><tr><td>7</td><td>现代演进选题口径（GoF 之后模式往哪走）</td><td>[S2][S3]</td><td><a href="/hello-design-patterns/evolution/overview">现代演进导读</a></td></tr><tr><td>8</td><td>组合优于继承 / 组合式设计</td><td>[S1][S2][S22][S23]</td><td><a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a></td></tr><tr><td>9</td><td>SOLID 五原则与依赖规则</td><td>[S3][S4]</td><td><a href="/hello-design-patterns/evolution/solid">SOLID 与依赖规则</a></td></tr><tr><td>10</td><td>熔断器（Circuit Breaker）</td><td>[S12]</td><td><a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a></td></tr><tr><td>11</td><td>线程池（概览已声明、站内无页）</td><td>[S19]</td><td><a href="/hello-design-patterns/concurrency/thread-pool">线程池</a></td></tr><tr><td>12</td><td>读写锁（概览已声明、站内无页）</td><td>[S19]</td><td><a href="/hello-design-patterns/concurrency/read-write-lock">读写锁</a></td></tr><tr><td>13</td><td>工作窃取（概览已声明、站内无页）</td><td>[S19]</td><td><a href="/hello-design-patterns/concurrency/work-stealing">工作窃取</a></td></tr><tr><td>14</td><td>事务脚本（概览已声明、站内无页）</td><td>[S5]</td><td><a href="/hello-design-patterns/other/transaction-script">事务脚本</a></td></tr></tbody></table><p>14 项缺口全部补齐，<code>gaps_filled = 14</code>。</p><h3 id="_2b-调研到、本次不新增的条目" tabindex="-1">2b. 调研到、本次不新增的条目 <a class="header-anchor" href="#_2b-调研到、本次不新增的条目" aria-label="Permalink to “2b. 调研到、本次不新增的条目”">​</a></h3><p>不新增的都写明理由，避免下次调研重复翻账。</p><table tabindex="0"><thead><tr><th>条目</th><th>来源</th><th>处置与理由</th></tr></thead><tbody><tr><td>空对象（Null Object）</td><td>[S16]</td><td>已按口径并入<a href="/hello-design-patterns/behavioral/strategy">策略模式</a>一节（2026-10-10），不单开一篇</td></tr><tr><td>仓储、单元工作</td><td>[S5][S11]</td><td>已于 2026-10-10 补齐（见表 2c），口径：仓储=聚合根↔持久化的领域层接口，ORM 管表↔对象映射</td></tr><tr><td>活动记录、表网关、行数据网关</td><td>[S5]</td><td>已由 <a href="/hello-design-patterns/other/orm">ORM 篇</a>覆盖，不重复成篇</td></tr><tr><td>前端控制器、页面控制器、模板视图</td><td>[S5]</td><td>部分由 <a href="/hello-design-patterns/other/mvc">MVC 篇</a>覆盖，暂不单独成篇</td></tr><tr><td>远程外观、数据传输对象</td><td>[S5]</td><td>与<a href="/hello-design-patterns/structural/remote-proxy">远程代理</a>角度不同，暂不新增，记为候选</td></tr><tr><td>分层架构、管道-过滤器、黑板、微内核</td><td>[S9]</td><td>属架构风格而非对象级模式，需先定&quot;架构风格与模式的边界&quot;再开分区</td></tr><tr><td>半同步/半异步</td><td>[S9]</td><td>与<a href="/hello-design-patterns/concurrency/active-object">主动对象</a>重叠，暂不新增</td></tr><tr><td>隔舱、超时、重试、稳态</td><td>[S12]</td><td>隔舱、超时、重试已于 2026-10-10 补齐（见表 2c）；稳态属容量纪律而非可封装模式，不单独成篇</td></tr><tr><td>消息通道、消息路由、消息转换、发布订阅</td><td>[S10]</td><td>需要先决定是否开&quot;集成模式&quot;分区</td></tr><tr><td>聚合、限界上下文、规格</td><td>[S11]</td><td>战略设计词汇，不在本仓&quot;模式&quot;口径内</td></tr><tr><td>API 网关、服务发现、Saga、Sidecar</td><td>[S13][S15]</td><td>分布式系统设计，不在现有口径内</td></tr><tr><td>类别对象、环境对象等纯社区条目</td><td>[S18]</td><td>无书籍出处，不收录</td></tr></tbody></table><h3 id="_2c-2026-10-10-增量" tabindex="-1">2c. 2026-10-10 增量 <a class="header-anchor" href="#_2c-2026-10-10-增量" aria-label="Permalink to “2c. 2026-10-10 增量”">​</a></h3><p>表 2b 里稳定性模式一行按下表落地：</p><table tabindex="0"><thead><tr><th>条目</th><th>来源</th><th>新篇</th></tr></thead><tbody><tr><td>隔舱（Bulkhead）</td><td>[S12]</td><td><a href="/hello-design-patterns/evolution/bulkhead">隔舱</a></td></tr><tr><td>超时（Timeout）</td><td>[S12]</td><td><a href="/hello-design-patterns/evolution/timeout">超时</a></td></tr><tr><td>重试（Retry）</td><td>[S12]</td><td><a href="/hello-design-patterns/evolution/retry">重试</a></td></tr><tr><td>稳态（Steady State）</td><td>[S12]</td><td>不单独成篇。它讲&quot;每个可消耗的资源都要有补充机制&quot;，是容量与降级的运维纪律，不是可封装的对象级模式</td></tr></tbody></table><p>补齐后文档总数 75 → 78，模式正文 61 → 64。</p><p>2026-10-10 同日再补一项：</p><table tabindex="0"><thead><tr><th>条目</th><th>来源</th><th>新篇</th></tr></thead><tbody><tr><td>仓储、单元工作</td><td>[S5][S11]</td><td><a href="/hello-design-patterns/other/repository">仓储与单元工作</a></td></tr></tbody></table><p>口径：仓储=聚合根↔持久化的领域层接口（接口在领域层、实现落基础设施层），ORM 管表↔对象映射。补齐后文档总数 78 → 79，模式正文 64 → 65。</p><h2 id="表-3-站内交叉引用不一致-6-处-已修订" tabindex="-1">表 3：站内交叉引用不一致（6 处，已修订） <a class="header-anchor" href="#表-3-站内交叉引用不一致-6-处-已修订" aria-label="Permalink to “表 3：站内交叉引用不一致（6 处，已修订）”">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>位置</th><th>问题</th><th>处置</th></tr></thead><tbody><tr><td>1</td><td><a href="/hello-design-patterns/reference">参考资料</a> 智能指针条目</td><td>写成&quot;智能指引模式&quot;</td><td>改为&quot;智能指针模式&quot;</td></tr><tr><td>2</td><td><a href="/hello-design-patterns/introduction">设计模式概览</a> 行为型清单</td><td>漏列站内已有的 DSL 篇</td><td>补列 DSL 条目</td></tr><tr><td>3</td><td><a href="/hello-design-patterns/concurrency/overview">并发模式导读</a></td><td>未列线程池、读写锁、工作窃取</td><td>三条补进目录清单与选用建议</td></tr><tr><td>4</td><td><a href="/hello-design-patterns/other/overview">其他模式导读</a></td><td>未列事务脚本</td><td>补进目录清单</td></tr><tr><td>5</td><td><a href="/hello-design-patterns/introduction">设计模式概览</a> 结尾</td><td>没有反模式与现代演进的入口</td><td>补两个分区入口</td></tr><tr><td>6</td><td><a href="/hello-design-patterns/reference">参考资料</a> 站内索引</td><td>未收录反模式、现代演进、调研三组</td><td>索引补齐，并补 AntiPatterns、Release It!、DDD 等书目</td></tr></tbody></table><p>另外一处一并处理：<a href="/hello-design-patterns/behavioral/snapshot">快照模式</a>页是合并到备忘录模式的跳转页，侧栏不收录，参考页保留指向，不做改动。</p><h2 id="新增页面清单-19-篇" tabindex="-1">新增页面清单（19 篇） <a class="header-anchor" href="#新增页面清单-19-篇" aria-label="Permalink to “新增页面清单（19 篇）”">​</a></h2><p>模式缺口 14 篇见表 2a，另有调研 5 篇：</p><ul><li><a href="/hello-design-patterns/research/overview">调研总览</a>：范围、方法、结论与 28 条来源清单</li><li><a href="/hello-design-patterns/research/books">权威书籍与标准目录</a>：15 本书逐本对照</li><li><a href="/hello-design-patterns/research/official-docs">官方与社区文档</a>：8 个官方文档与 3 个社区站点</li><li><a href="/hello-design-patterns/research/applications">应用场景与语言落地</a>：场景到 API 的对照表</li><li>本页：覆盖核对与差异表</li></ul><h2 id="核对与验收方式" tabindex="-1">核对与验收方式 <a class="header-anchor" href="#核对与验收方式" aria-label="Permalink to “核对与验收方式”">​</a></h2><ol><li>站内文件清单用 <code>git ls-files docs | grep &#39;\\.md$&#39;</code> 取，不靠记忆。</li><li>新增页面的站内链接一律写成绝对路径（<code>/分区/文件</code>），由 VitePress 的死链检查兜底：<code>npm run docs:build</code> 不通过视为未完成。</li><li>GoF 23 条逐条对过文件名，见表 1。</li><li>引用的 API 名称以 Java SE、C++ Core Guidelines、Go、Vue、React 官方文档为准，见<a href="/hello-design-patterns/research/official-docs">官方与社区文档</a>。</li><li>补完后文档总数 56 → 75，其中模式正文 47 → 61。</li></ol>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};